import pandas as pd
import numpy as np


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and np.isnan(v):
            return True
    except Exception:
        pass
    try:
        if pd.isna(v):
            return True
    except Exception:
        pass
    return False


def _changed(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _get_input(inputs, name):
    if name in inputs:
        return inputs[name]
    # try case-insensitive match
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    # try suffix/substring match as fallback
    for k, v in inputs.items():
        if lname in k.lower() or k.lower() in lname:
            return v
    raise KeyError(f"Could not find input matching '{name}' among {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_PRODUCT").copy()
    stg = _get_input(inputs, "STG_PRODUCT").copy()

    # Normalize dim columns/types
    dim_cols = ["product_id", "category", "price_band",
                "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = pd.NA
    dim = dim[dim_cols].copy()

    # Coerce date columns to datetime for correct comparisons/output
    if not pd.api.types.is_datetime64_any_dtype(dim["eff_start_date"]):
        dim["eff_start_date"] = pd.to_datetime(dim["eff_start_date"], errors="coerce")
    if not pd.api.types.is_datetime64_any_dtype(dim["eff_end_date"]):
        dim["eff_end_date"] = pd.to_datetime(dim["eff_end_date"], errors="coerce")

    dim["is_current"] = dim["is_current"].astype("Int64")

    # Build working state: list of row dicts (mutable)
    records = dim.to_dict("records")

    # Index of current row position per product_id -> index in records list
    current_index = {}
    for idx, r in enumerate(records):
        if not _is_null(r.get("is_current")) and int(r["is_current"]) == 1:
            pid = r["product_id"]
            # In case of multiple currents (shouldn't happen), keep last seen
            current_index[pid] = idx

    # Prepare staging: ensure update_date is datetime, sort by product_id, update_date asc
    stg["update_date"] = pd.to_datetime(stg["update_date"], errors="coerce")
    stg_sorted = stg.sort_values(
        by=["product_id", "update_date"],
        kind="mergesort"
    ).reset_index(drop=True)

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_cat = s["category"]
        s_pb = s["price_band"]
        s_date = s["update_date"]

        if pid in current_index:
            idx = current_index[pid]
            c = records[idx]
            cat_changed = _changed(c["category"], s_cat)
            pb_changed = _changed(c["price_band"], s_pb)
            if cat_changed or pb_changed:
                # expire current
                records[idx]["eff_end_date"] = s_date
                records[idx]["is_current"] = 0
                # insert new current version
                new_row = {
                    "product_id": pid,
                    "category": s_cat,
                    "price_band": s_pb,
                    "eff_start_date": s_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
                records.append(new_row)
                current_index[pid] = len(records) - 1
            else:
                # no-op
                pass
        else:
            # no current row exists -> insert new current version
            new_row = {
                "product_id": pid,
                "category": s_cat,
                "price_band": s_pb,
                "eff_start_date": s_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            }
            records.append(new_row)
            current_index[pid] = len(records) - 1

    out = pd.DataFrame(records, columns=dim_cols)
    out["is_current"] = out["is_current"].astype("Int64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"], errors="coerce")
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"], errors="coerce")

    return {"dim_product_out": out}
